inb = {'A1': 485, 'A2': 512, 'A3': 538}
out = {'B1': 545, 'B2': 580, 'B3': 605}
MCT = 45
feasible = []
for a, ta in inb.items():
    for b, tb in out.items():
        if tb - ta >= MCT:
            feasible.append((a, b, tb - ta))
print('feasible connections:', len(feasible), 'of', len(inb) * len(out))
for a, b, slack in feasible:
    print(a, '->', b, 'slack', slack, 'min')
print('tightest:', min(feasible, key=lambda x: x[2]))

chain = [('Alvarez', 1848, 1879), ('Brooks', 1879, 1903), ('Chen', 1903, 1926), ('Doyle', 1931, 1958), ('Osei', 1958, 1990), ('Park', 1990, 2026)]
gaps = []
for (n1, f1, t1), (n2, f2, t2) in zip(chain, chain[1:]):
    if f2 != t1:
        gaps.append((n1, n2, t1, f2, f2 - t1))
print('links checked:', len(chain) - 1)
for g in gaps:
    print('GAP:', g[0], 'ends', g[2], 'but', g[1], 'begins', g[3], '- missing', g[4], 'years')
print('total span covered:', chain[-1][2] - chain[0][1], 'years')

owes = {('A','B'):40, ('A','C'):15, ('A','D'):5, ('B','A'):25, ('B','C'):30, ('B','D'):10, ('C','A'):10, ('C','B'):20, ('C','D'):35, ('D','A'):15, ('D','B'):5, ('D','C'):25}
net = {}
for (payer, payee), amt in owes.items():
    net[payer] = net.get(payer, 0) - amt
    net[payee] = net.get(payee, 0) + amt
gross = sum(owes.values())
settle = sum(v for v in net.values() if v > 0)
for b in sorted(net):
    print(b, 'net position:', net[b])
print('gross obligations:', gross)
print('net settlement total:', settle)
print('liquidity saved:', round((1 - settle / gross) * 100, 1), '%')

